document.getElementById("year").textContent=(new Date).getFullYear();(function handleVideoPlayback(){const video=document.getElementById("genesisVideoY")||document.querySelector(".genesis-y-video");if(!video)return;const connection=navigator.connection||navigator.mozConnection||navigator.webkitConnection;const effectiveType=connection?connection.effectiveType:"4g";const isSlowConnection=effectiveType==="2g"||effectiveType==="3g"||effectiveType==="slow-2g";const prefersReducedMotion=window.matchMedia&&window.matchMedia("(prefers-reduced-motion: reduce)").matches;if(!isSlowConnection&&!prefersReducedMotion){video.preload="auto";const playPromise=video.play();if(playPromise){playPromise.catch(()=>{})}}else{video.preload="metadata"}})();const nav=document.getElementById("mainNav");window.addEventListener("scroll",()=>{if(window.scrollY>100){nav.classList.add("scrolled")}else{nav.classList.remove("scrolled")}});const fadeElements=document.querySelectorAll(".fade-in");const observer=new IntersectionObserver(entries=>{entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add("visible")}})},{threshold:.1});fadeElements.forEach(el=>observer.observe(el));const parallaxElements=document.querySelectorAll(".parallax");window.addEventListener("mousemove",e=>{const x=(e.clientX/window.innerWidth-.5)*20;const y=(e.clientY/window.innerHeight-.5)*20;parallaxElements.forEach((el,index)=>{const depth=(index+1)*.5;el.style.transform=`translate(${x*depth}px, ${y*depth}px)`})});const cards=document.querySelectorAll(".presentation-card");cards.forEach(card=>{card.addEventListener("mousemove",e=>{const rect=card.getBoundingClientRect();const x=e.clientX-rect.left;const y=e.clientY-rect.top;const centerX=rect.width/2;const centerY=rect.height/2;const rotateX=(y-centerY)/centerY*-10;const rotateY=(x-centerX)/centerX*10;card.style.transform=`translateY(-8px) scale(1.02) perspective(1000px) rotateX(${rotateX}deg) rotateY(${rotateY}deg)`});card.addEventListener("mouseleave",()=>{card.style.transform=""})});function loadProgress(){const presentations=document.querySelectorAll(".presentation-card");presentations.forEach(card=>{const presentationId=card.dataset.presentation;if(!presentationId)return;const storageKey=`genesis-presentation-${presentationId}-progress`;const progress=localStorage.getItem(storageKey)||"0";const progressFill=card.querySelector(".progress-fill");const progressText=card.querySelector(".progress-text");if(progressFill&&progressText){progressFill.style.width=`${progress}%`;progressFill.dataset.progress=progress;progressText.textContent=`${progress}%`}})}function saveProgress(presentationId,progress){const storageKey=`genesis-presentation-${presentationId}-progress`;localStorage.setItem(storageKey,progress.toString())}loadProgress();let touchStartX=0;let touchStartY=0;cards.forEach(card=>{card.addEventListener("touchstart",e=>{touchStartX=e.touches[0].clientX;touchStartY=e.touches[0].clientY});card.addEventListener("touchmove",e=>{if(!touchStartX||!touchStartY)return;const touchEndX=e.touches[0].clientX;const touchEndY=e.touches[0].clientY;const diffX=touchStartX-touchEndX;const diffY=touchStartY-touchEndY;if(Math.abs(diffX)>Math.abs(diffY)){if(Math.abs(diffX)>50){}}});card.addEventListener("touchend",()=>{touchStartX=0;touchStartY=0})});const particleCanvas=document.getElementById("particleCanvas");const particleCtx=particleCanvas.getContext("2d");function resizeParticleCanvas(){particleCanvas.width=window.innerWidth;particleCanvas.height=document.querySelector(".hero").offsetHeight}resizeParticleCanvas();window.addEventListener("resize",resizeParticleCanvas);class Particle{constructor(){this.x=Math.random()*particleCanvas.width;this.y=Math.random()*particleCanvas.height;this.size=Math.random()*2+.5;this.speedX=(Math.random()-.5)*.5;this.speedY=(Math.random()-.5)*.5;this.opacity=Math.random()*.5+.2}update(){this.x+=this.speedX;this.y+=this.speedY;if(this.x>particleCanvas.width)this.x=0;if(this.x<0)this.x=particleCanvas.width;if(this.y>particleCanvas.height)this.y=0;if(this.y<0)this.y=particleCanvas.height}draw(){particleCtx.fillStyle=`rgba(168, 168, 168, ${this.opacity})`;particleCtx.beginPath();particleCtx.arc(this.x,this.y,this.size,0,Math.PI*2);particleCtx.fill()}}const particleCount=100;const particles=[];for(let i=0;i<particleCount;i++){particles.push(new Particle)}function animateParticles(){particleCtx.clearRect(0,0,particleCanvas.width,particleCanvas.height);particles.forEach(particle=>{particle.update();particle.draw()});for(let i=0;i<particles.length;i++){for(let j=i+1;j<particles.length;j++){const dx=particles[i].x-particles[j].x;const dy=particles[i].y-particles[j].y;const distance=Math.sqrt(dx*dx+dy*dy);if(distance<100){particleCtx.strokeStyle=`rgba(168, 168, 168, ${.1*(1-distance/100)})`;particleCtx.lineWidth=.5;particleCtx.beginPath();particleCtx.moveTo(particles[i].x,particles[i].y);particleCtx.lineTo(particles[j].x,particles[j].y);particleCtx.stroke()}}}requestAnimationFrame(animateParticles)}animateParticles();const waveCanvas=document.getElementById("waveCanvas");const waveCtx=waveCanvas.getContext("2d");function resizeWaveCanvas(){waveCanvas.width=window.innerWidth;waveCanvas.height=document.querySelector(".hero").offsetHeight}resizeWaveCanvas();window.addEventListener("resize",resizeWaveCanvas);let waveOffset=0;function drawWave(offset,amplitude,frequency,color,alpha){waveCtx.beginPath();waveCtx.moveTo(0,waveCanvas.height/2);for(let x=0;x<waveCanvas.width;x++){const y=Math.sin((x+offset)*frequency)*amplitude+waveCanvas.height/2;waveCtx.lineTo(x,y)}waveCtx.lineTo(waveCanvas.width,waveCanvas.height);waveCtx.lineTo(0,waveCanvas.height);waveCtx.closePath();const gradient=waveCtx.createLinearGradient(0,0,0,waveCanvas.height);gradient.addColorStop(0,`rgba(${color}, 0)`);gradient.addColorStop(.5,`rgba(${color}, ${alpha*.5})`);gradient.addColorStop(1,`rgba(${color}, ${alpha})`);waveCtx.fillStyle=gradient;waveCtx.fill()}function animateWaves(){waveCtx.clearRect(0,0,waveCanvas.width,waveCanvas.height);drawWave(waveOffset*.5,30,.005,"177, 15, 26",.03);drawWave(waveOffset*.8,20,.008,"139, 0, 0",.02);drawWave(waveOffset*1.2,40,.003,"102, 0, 0",.015);waveOffset+=1;requestAnimationFrame(animateWaves)}animateWaves();let mouseX=0;let mouseY=0;document.addEventListener("mousemove",e=>{mouseX=e.clientX;mouseY=e.clientY;particles.forEach(particle=>{const dx=particle.x-mouseX;const dy=particle.y-mouseY;const distance=Math.sqrt(dx*dx+dy*dy);if(distance<100){const force=(100-distance)/100;particle.x+=dx/distance*force*2;particle.y+=dy/distance*force*2}})});window.genesisPresentation={saveProgress:saveProgress,loadProgress:loadProgress};